-- CC_0027_milledgeville_structure.sql
--
-- Knight Foundation cities program, wave GA-3, CITY STRUCTURE half.
--   * 1 government, 2 chambers
--   * 7 districts -- 1 citywide (TIGER place 1351492/G4110) + 6 council (X0042)
--   * 7 offices   -- 1 Mayor + 6 single-member council members
--
-- Plan:   docs/superpowers/plans/2026-09-01-knight-ga-wave-3-milledgeville-baldwin.md
-- Roster: backend/data/seed-milledgeville-2026/ROSTERS.md
-- Generated by scripts/gen-ga3-milledgeville-migrations.mjs -- edit the roster
-- JSON and regenerate, do not hand-edit this file.
--
-- 🔴 TAKE THE MIGRATION NUMBER LAST. Re-count against EVERY remote ref, not
--    against PROGRAM.md. Verified 2026-09-01: CC_0026 was the highest slot
--    across all 81 remote refs.
--
-- ---------------------------------------------------------------------------
-- 🔴 RULING R1: THE MAYOR IS voting_powers 'full', IN A CHAMBER OF ONE.
--
-- Follows Bradenton's ruling R2 (CC_0008): voting_powers describes the powers of
-- the OFFICE, not a council procedure. Milledgeville's Mayor is elected citywide
-- on a separate certified ballot line ("Mayor - Milledgeville", Georgia SOS) for
-- a four-year term, and is not a seat that exists only to preside -- which is
-- what made Nashville's Vice Mayor non_voting.
--
-- ⚠ THE MAYOR'S VOTE ON THE COUNCIL IS NOT ESTABLISHED. The only published
--   charter is codified through JANUARY 2014 and is titled "ARTICLE II. -- MAYOR
--   AND ALDERMEN"; it describes no six-district council at all. Milledgeville is
--   council-MANAGER, so unlike Bradenton the Mayor is not the chief executive.
--   'full' requires no representation_note, so this ruling writes NO unsourced
--   prose into a voter-facing field. Re-check when a current charter is found.
--
-- 🔴 RULING R2: MAYOR PRO-TEM IS A ROLE, NOT AN OFFICE. The council elects it
--    from among its own members (currently Denese Shinholster, District 3). The
--    post-verify gate refuses any office whose title contains "pro-tem".
--
-- ⚠ THE COUNCIL IS NOT STAGGERED. All six districts and the mayoralty were on
--   the SAME November 2025 ballot, confirmed against the Georgia Secretary of
--   State's certified municipal results.

BEGIN;

-- --- 0. Pre-flight: refuse to create offices whose district has no polygon ---
-- 🔴 An office on a district with no boundary is an office NOBODY CAN REACH BY
-- ADDRESS, and nothing else in the system errors. This is the only failure mode
-- CI cannot catch after the fact.
DO $$
DECLARE v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM essentials.geofence_boundaries WHERE mtfcc = 'X0042';
  IF v_n <> 6 THEN
    RAISE EXCEPTION 'milledgeville structure: expected 6 X0042 boundaries, found % -- run the GA-3 boundary loader first', v_n;
  END IF;

  -- ⚠ ALWAYS PAIR geo_id WITH mtfcc. Georgia's collision is THREE-WAY: bare
  -- '13009' is Baldwin County AND State House District 9 AND State Senate
  -- District 9, and all three rows are in production.
  IF NOT EXISTS (
    SELECT 1 FROM essentials.geofence_boundaries
     WHERE geo_id = '1351492' AND mtfcc = 'G4110'
  ) THEN
    RAISE EXCEPTION 'milledgeville structure: boundary 1351492/G4110 is missing -- GA-1 must be applied first';
  END IF;

END $$;

-- --- 1. Districts -----------------------------------------------------------
-- ⚠ Synthetic districts carry no ocd_id and no government_id, matching X0036
-- and X0041. district state is LOWER case here and UPPER on governments and
-- offices; both conventions are live in prod.

INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville Citywide', 'ga', '1351492', 'G4110', NULL
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = '1351492' AND mtfcc = 'G4110' AND district_type = 'LOCAL'
);
INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville City Council District 1', 'ga', 'milledgeville-ga-council-district-1', 'X0042', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'milledgeville-ga-council-district-1' AND mtfcc = 'X0042' AND district_type = 'LOCAL'
);
INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville City Council District 2', 'ga', 'milledgeville-ga-council-district-2', 'X0042', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'milledgeville-ga-council-district-2' AND mtfcc = 'X0042' AND district_type = 'LOCAL'
);
INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville City Council District 3', 'ga', 'milledgeville-ga-council-district-3', 'X0042', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'milledgeville-ga-council-district-3' AND mtfcc = 'X0042' AND district_type = 'LOCAL'
);
INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville City Council District 4', 'ga', 'milledgeville-ga-council-district-4', 'X0042', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'milledgeville-ga-council-district-4' AND mtfcc = 'X0042' AND district_type = 'LOCAL'
);
INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville City Council District 5', 'ga', 'milledgeville-ga-council-district-5', 'X0042', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'milledgeville-ga-council-district-5' AND mtfcc = 'X0042' AND district_type = 'LOCAL'
);
INSERT INTO essentials.districts (district_type, label, state, geo_id, mtfcc, num_officials)
SELECT 'LOCAL', 'Milledgeville City Council District 6', 'ga', 'milledgeville-ga-council-district-6', 'X0042', 1
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.districts
   WHERE geo_id = 'milledgeville-ga-council-district-6' AND mtfcc = 'X0042' AND district_type = 'LOCAL'
);

-- --- 2. Government ----------------------------------------------------------

INSERT INTO essentials.governments (name, type, state, city, geo_id)
SELECT 'City of Milledgeville, Georgia, US', 'City', 'GA', 'Milledgeville', '1351492'
WHERE NOT EXISTS (
  SELECT 1 FROM essentials.governments WHERE geo_id = '1351492' AND type = 'City'
);

-- --- 3. Chambers ------------------------------------------------------------
-- ⚠ chambers.slug is GENERATED from name_formal and cannot be inserted.
-- Getting name_formal wrong silently yields a different slug.

INSERT INTO essentials.chambers
  (government_id, name, name_formal, official_count, policy_engagement_level)
SELECT g.id, 'City Council', 'Milledgeville City Council', 6, 'full'
FROM essentials.governments g
WHERE g.geo_id = '1351492' AND g.type = 'City'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.chambers c WHERE c.government_id = g.id AND c.name = 'City Council'
  );

INSERT INTO essentials.chambers
  (government_id, name, name_formal, official_count, policy_engagement_level)
SELECT g.id, 'Office of the Mayor', 'Office of the Mayor of Milledgeville', 1, 'full'
FROM essentials.governments g
WHERE g.geo_id = '1351492' AND g.type = 'City'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.chambers c WHERE c.government_id = g.id AND c.name = 'Office of the Mayor'
  );

-- --- 4. Offices -------------------------------------------------------------
-- Every title is distinct, so a NOT EXISTS-on-title guard cannot collapse rows.

INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Mayor', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = '1351492' AND dd.mtfcc = 'G4110'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'Office of the Mayor'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Mayor'
  );
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Council Member, District 1', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = 'milledgeville-ga-council-district-1' AND dd.mtfcc = 'X0042'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'City Council'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Council Member, District 1'
  );
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Council Member, District 2', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = 'milledgeville-ga-council-district-2' AND dd.mtfcc = 'X0042'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'City Council'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Council Member, District 2'
  );
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Council Member, District 3', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = 'milledgeville-ga-council-district-3' AND dd.mtfcc = 'X0042'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'City Council'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Council Member, District 3'
  );
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Council Member, District 4', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = 'milledgeville-ga-council-district-4' AND dd.mtfcc = 'X0042'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'City Council'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Council Member, District 4'
  );
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Council Member, District 5', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = 'milledgeville-ga-council-district-5' AND dd.mtfcc = 'X0042'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'City Council'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Council Member, District 5'
  );
INSERT INTO essentials.offices
  (chamber_id, district_id, title, representing_state, representing_city, voting_powers)
SELECT c.id, d.id, 'Council Member, District 6', 'GA', 'Milledgeville', 'full'
FROM essentials.chambers c
JOIN essentials.governments g ON g.id = c.government_id
CROSS JOIN LATERAL (
  SELECT dd.id FROM essentials.districts dd
   WHERE dd.geo_id = 'milledgeville-ga-council-district-6' AND dd.mtfcc = 'X0042'
     AND dd.district_type = 'LOCAL' AND lower(dd.state) = 'ga'
) d
WHERE g.geo_id = '1351492' AND g.type = 'City' AND c.name = 'City Council'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.offices o
    WHERE o.chamber_id = c.id AND o.district_id = d.id AND o.title = 'Council Member, District 6'
  );

-- --- 5. Post-verify gate ----------------------------------------------------
DO $$
DECLARE v_n int; v_gov uuid; v_d text; v_desc int;
BEGIN
  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE mtfcc = 'X0042' AND district_type = 'LOCAL' AND lower(state) = 'ga';
  IF v_n <> 6 THEN RAISE EXCEPTION 'milledgeville structure: expected 6 X0042 districts, got %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE geo_id = '1351492' AND mtfcc = 'G4110' AND district_type = 'LOCAL';
  IF v_n <> 1 THEN RAISE EXCEPTION 'milledgeville structure: expected exactly 1 Milledgeville Citywide district, got %', v_n; END IF;

  SELECT id INTO v_gov FROM essentials.governments
   WHERE geo_id = '1351492' AND type = 'City';
  IF v_gov IS NULL THEN RAISE EXCEPTION 'milledgeville structure: the government row is missing'; END IF;

  SELECT count(*) INTO v_n FROM essentials.chambers WHERE government_id = v_gov;
  IF v_n <> 2 THEN RAISE EXCEPTION 'milledgeville structure: expected 2 chambers, got %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.chambers
   WHERE government_id = v_gov AND ((name = 'City Council' AND official_count = 6)
                                 OR (name = 'Office of the Mayor' AND official_count = 1));
  IF v_n <> 2 THEN RAISE EXCEPTION 'milledgeville structure: chamber names or official_counts are wrong'; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov;
  IF v_n <> 7 THEN RAISE EXCEPTION 'milledgeville structure: expected 7 offices, got %', v_n; END IF;

  -- Exactly one office per numbered district, counted PER DISTRICT. A single
  -- total can hide two offices on one district and none on another.
  FOR v_d IN SELECT 'milledgeville-ga-council-district-' || gs FROM generate_series(1,6) gs LOOP
    SELECT count(*) INTO v_n FROM essentials.offices o
      JOIN essentials.districts d ON d.id = o.district_id
     WHERE d.geo_id = v_d AND d.mtfcc = 'X0042' AND d.district_type = 'LOCAL';
    IF v_n <> 1 THEN RAISE EXCEPTION 'milledgeville structure: district % carries % offices, expected exactly 1', v_d, v_n; END IF;
  END LOOP;

  -- The at-large offices sit on the wide district.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov AND d.geo_id = '1351492' AND d.mtfcc = 'G4110'
     AND d.district_type = 'LOCAL';
  IF v_n <> 1 THEN RAISE EXCEPTION 'milledgeville structure: expected 1 office(s) on Milledgeville Citywide, got %', v_n; END IF;

  -- No role leaked out as its own office. Mayor Pro-Tem is a role the council
  -- elects from among its members (ruling R2), not an office.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov
     AND (o.title ILIKE '%pro-tem%' OR o.title ILIKE '%pro tem%' OR o.title ILIKE '%chair%');
  IF v_n <> 0 THEN RAISE EXCEPTION 'milledgeville structure: % role(s) were created as offices -- ruling R2 says they are parentheticals', v_n; END IF;

  -- 🔴 No office may sit on a district with no matching boundary: that is an
  -- office nobody can reach by address, and nothing else errors.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE c.government_id = v_gov
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb
                      WHERE gb.geo_id = d.geo_id AND gb.mtfcc = d.mtfcc);
  IF v_n <> 0 THEN RAISE EXCEPTION 'milledgeville structure: % office(s) sit on a district with no matching boundary', v_n; END IF;

  RAISE NOTICE 'milledgeville structure OK: 7 district(s) created, 1 government, 2 chambers, 7 offices';
END $$;

COMMIT;
